/* min-width: 1024px \u3092\u7DE9\u3081\u3066\u6A2A\u30B9\u30AF\u30ED\u30FC\u30EB\u306A\u3057\u3067 GUI \u304C\u8868\u793A\u3055\u308C\u308B\u3088\u3046\u306B  */
